1845|	{
1846|	  struct local_symbol *locsym = (struct local_symbol *) symbolP;
1847|
1848|	  *valueP = locsym->value;
1849|	  *segP = locsym->section;
1850|	  *fragPP = locsym->frag;
1851|	}
