3191|void
3192|print_expr_1 (FILE *file, expressionS *exp)
3193|{
3194|  fprintf (file, "expr ");
3195|  fprintf_vma (file, (bfd_vma) (uintptr_t) exp);
3196|  fprintf (file, " ");
3197|  switch (exp->X_op)
