1650|	  /* Check for division by zero.  */
1651|	  if ((op == O_divide || op == O_modulus) && right == 0)
1652|	    {
1653|	      /* If seg_right is not absolute_section, then we've
1654|		 already issued a warning about using a bad symbol.  */
