1717|	      abort ();
1718|	    }
1719|
1720|	  final_val += symp->frag->fr_address + left;
1721|	  if (final_seg == expr_section || final_seg == undefined_section)
1722|	    {
1723|	      if (seg_left == undefined_section
1724|		  || seg_right == undefined_section)
1725|		final_seg = undefined_section;
